before.code:
btn.onclick = async () => {
  const url = await fetchShareUrl();
  await navigator.clipboard.writeText(url); // Activation expired!
};

after.code:
btn.onclick = () => {
  const item = new ClipboardItem({
    'text/plain': fetchShareUrl().then((u) => new Blob([u], { type: 'text/plain' })),
  });
  navigator.clipboard.write([item]);
};
